import { describe, expect, it } from 'vitest';

import { normalizedDatasetSchema, validationReportSchema } from '../src/index.js';
import normalizedFixture from './fixtures/normalized-dataset.json' with { type: 'json' };
import reportFixture from './fixtures/validation-report.json' with { type: 'json' };

// These files are generated by the Python data-processor (`python -m app.contract_fixtures`)
// from samples/datasets/synthetic-ranking.csv. Parsing them here proves that what Python
// writes is what TypeScript accepts.
describe('cross-language contract fixtures', () => {
  it('the normalized dataset written by the data-processor matches the Zod schema', () => {
    const result = normalizedDatasetSchema.safeParse(normalizedFixture);
    expect(result.error?.issues).toBeUndefined();
    const dataset = result.data!;
    expect(dataset.timeRange.periods).toEqual(['2015', '2016', '2017', '2018', '2019', '2020']);
    expect(dataset.rankings[0]?.entries.map((e) => [e.entityId, e.rank, e.position])).toEqual([
      ['AUR', 1, 1],
      ['BRK', 2, 2],
      ['CDR', 2, 3],
      ['DLT', 4, 4],
    ]);
    expect(dataset.frames.some((frame) => frame.isEstimate)).toBe(true);
    // Empty optional cells are null, never the string "nan".
    expect(dataset.observations.find((o) => o.row === 3)?.notes).toBeNull();
    expect(JSON.stringify(normalizedFixture)).not.toMatch(/"nan"/i);
  });

  it('the validation report matches the Zod schema', () => {
    const result = validationReportSchema.safeParse(reportFixture);
    expect(result.error?.issues).toBeUndefined();
    expect(result.data?.issues.map((issue) => issue.code)).toContain('MISSING_VALUE');
  });

  it('rejects a normalized dataset with an unknown value kind', () => {
    const tampered = JSON.parse(JSON.stringify(normalizedFixture)) as typeof normalizedFixture;
    tampered.rankings[0]!.entries[0]!.valueKind = 'guessed';
    expect(normalizedDatasetSchema.safeParse(tampered).success).toBe(false);
  });
});
